czekaj_na_gotowosc() {
    local port=${1:?port} limit=${2:-120} start=$SECONDS
    until curl -fs -m 2 "localhost:$port/actuator/health/readiness" > /dev/null; do
        (( SECONDS - start >= limit )) && return 1
        sleep 2
    done
