$ cat ~/bin/pilnuj-sklepu.sh
#!/bin/bash
source /usr/local/lib/sklep/funkcje.sh
for p in 8080 8082; do
    if czekaj_na_gotowosc "$p" 10; then
        loguj "sklep@$p OK, wersja $(wersja_sklepu "$p")"
    else
        loguj "sklep@$p nie odpowiada - restart"
        sudo systemctl restart "sklep@$p"
        czekaj_na_gotowosc "$p" 120 || zakoncz "sklep@$p nie wstal po restarcie"
        loguj "sklep@$p gotowy po restarcie"
    fi
done
