zajete=$(procent_zajetosci /)
echo "zajetosc /: $zajete%"

licznik=100
zwieksz_globalnie() { licznik=$((licznik + 1)); }
zwieksz_lokalnie() { local licznik=0; licznik=$((licznik + 1)); echo "w funkcji: $licznik"; }
zwieksz_globalnie; zwieksz_lokalnie
echo "po wywolaniach: $licznik"

silnia() { local n=$1; if (( n <= 1 )); then echo 1; else echo $(( n * $(silnia $((n - 1))) )); fi; }
echo "5! = $(silnia 5)"
echo "10! = $(silnia 10)"

